CREATE TABLE IF NOT EXISTS site_health_sites (user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, origin TEXT NOT NULL, url TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, uptime_next_at TEXT NOT NULL, uptime_state TEXT CHECK(uptime_state IN ('up','down','error')), uptime_code INTEGER, uptime_ms INTEGER, uptime_detail TEXT, uptime_checked_at TEXT, uptime_fails INTEGER NOT NULL DEFAULT 0, uptime_down_since TEXT, uptime_incident_id TEXT, ssl_next_at TEXT NOT NULL, ssl_status TEXT CHECK(ssl_status IN ('ok','expiring','expired','invalid','no_https','unknown')), ssl_valid_to TEXT, ssl_issuer TEXT, ssl_names TEXT, ssl_detail TEXT, ssl_checked_at TEXT, ssl_alert TEXT, domain_next_at TEXT NOT NULL, domain_name TEXT, domain_status TEXT CHECK(domain_status IN ('ok','expiring','expired','unknown')), domain_expires_at TEXT, domain_registrar TEXT, domain_detail TEXT, domain_checked_at TEXT, domain_alert TEXT, PRIMARY KEY (user_id, origin));
CREATE INDEX IF NOT EXISTS site_health_uptime_due ON site_health_sites(active, uptime_next_at);
CREATE INDEX IF NOT EXISTS site_health_ssl_due ON site_health_sites(active, ssl_next_at);
CREATE INDEX IF NOT EXISTS site_health_domain_due ON site_health_sites(active, domain_next_at);
CREATE TABLE IF NOT EXISTS site_uptime_hourly (user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, origin TEXT NOT NULL, hour TEXT NOT NULL, checks INTEGER NOT NULL DEFAULT 0, down INTEGER NOT NULL DEFAULT 0, total_ms INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (user_id, origin, hour));
CREATE TABLE IF NOT EXISTS site_uptime_incidents (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, origin TEXT NOT NULL, started_at TEXT NOT NULL, ended_at TEXT, detail TEXT NOT NULL DEFAULT '', opened_alert_at TEXT, closed_alert_at TEXT);
CREATE INDEX IF NOT EXISTS site_uptime_incidents_site ON site_uptime_incidents(user_id, origin, started_at);
CREATE TABLE IF NOT EXISTS site_link_checks (watch_id TEXT PRIMARY KEY REFERENCES watches(id) ON DELETE CASCADE, user_id TEXT NOT NULL, next_at TEXT NOT NULL, checked_at TEXT, page_url TEXT, checked INTEGER NOT NULL DEFAULT 0, broken INTEGER NOT NULL DEFAULT 0, unverified INTEGER NOT NULL DEFAULT 0, detail TEXT);
CREATE INDEX IF NOT EXISTS site_link_checks_due ON site_link_checks(next_at);
CREATE TABLE IF NOT EXISTS site_broken_links (watch_id TEXT NOT NULL REFERENCES watches(id) ON DELETE CASCADE, url TEXT NOT NULL, user_id TEXT NOT NULL, status INTEGER, reason TEXT NOT NULL, link_text TEXT NOT NULL DEFAULT '', first_seen_at TEXT NOT NULL, last_seen_at TEXT NOT NULL, fixed_at TEXT, PRIMARY KEY (watch_id, url, first_seen_at));
CREATE INDEX IF NOT EXISTS site_broken_links_fixed ON site_broken_links(fixed_at);
